import AddIcon from '@jetbrains/icons/add.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Tooltip from '@jetbrains/ring-ui-built/components/tooltip/tooltip'
import classNames from 'classnames'
import {Suspense, useCallback, useMemo} from 'react'
import {EntryPointContainer} from 'react-relay'
import {useHref, useLinkClickHandler} from 'react-router'

import Routes, {getHref} from '../../../../../routes'
import SidebarSearch from '../../../../common/SidebarSearch/SidebarSearch'
import usePermissionCanEditProject from '../../../../pages/PipelinesPages/hooks/usePermissionCanEditProject'
import {
  getAccountRootProjectId,
  noPermissionToCreateMessage,
} from '../../../../pages/PipelinesPages/PipelinesPages.consts'
import SidebarHeader from '../SidebarHeader/SidebarHeader'
import SidebarHeaderShadow from '../SidebarHeaderShadow/SidebarHeaderShadow'
import {useSidebar, useSidebarScroll} from '../SidebarPanelContent.hooks'
import {getSidebarSearchPlaceholder} from '../SidebarPanelContent.utils'
import SidebarPanelContentLoading from '../SidebarPanelContentLoading/SidebarPanelContentLoading'

import {PipelinesSidebarSearchContext} from './PipelinesSidebar.contexts'
import type {Props} from './PipelinesSidebar.types'

import styles from './PipelinesSidebar.module.css'

function PipelinesSidebar(props: Props) {
  const {className, width, contentEntryPoint} = props
  const [scrollState, onScroll] = useSidebarScroll()
  const {
    collapsed,
    searchQuery,
    searchActive,
    changeSidebarSearchQuery,
    changeSidebarSearchActive,
  } = useSidebar()

  const pipelinesSidebarSearch = useMemo(
    () => ({searchQuery, searchActive, changeSidebarSearchQuery, changeSidebarSearchActive}),
    [changeSidebarSearchActive, changeSidebarSearchQuery, searchActive, searchQuery],
  )

  const rootId = getAccountRootProjectId()
  const canEditProject = usePermissionCanEditProject(rootId)
  const to = getHref(Routes.CREATE_PIPELINE)
  const href = useHref(to)
  const onClick = useLinkClickHandler(to)

  const renderSearch = useCallback(
    () => (
      <SidebarSearch
        placeholder={getSidebarSearchPlaceholder(width, 'Search by name')}
        {...pipelinesSidebarSearch}
      />
    ),
    [pipelinesSidebarSearch, width],
  )

  return useMemo(
    () => (
      <div className={classNames(className, styles.sidebar)}>
        <PipelinesSidebarSearchContext.Provider value={pipelinesSidebarSearch}>
          <SidebarHeaderShadow
            sidebarCollapsed={collapsed}
            showShadow={!collapsed && scrollState?.isScrollAtStart === false}
          >
            <SidebarHeader
              sidebarName={'Pipelines'}
              className={styles.header}
              search={renderSearch()}
              headerButton={
                <Tooltip
                  title={canEditProject ? 'Create new pipeline' : noPermissionToCreateMessage}
                >
                  <Button
                    disabled={!canEditProject}
                    icon={AddIcon}
                    aria-label="Create new pipeline"
                    href={href}
                    onClick={onClick}
                  />
                </Tooltip>
              }
            />
          </SidebarHeaderShadow>
          {!collapsed && (
            <Suspense fallback={<SidebarPanelContentLoading />}>
              <EntryPointContainer entryPointReference={contentEntryPoint} props={{onScroll}} />
            </Suspense>
          )}
        </PipelinesSidebarSearchContext.Provider>
      </div>
    ),
    [
      canEditProject,
      className,
      collapsed,
      contentEntryPoint,
      href,
      onClick,
      onScroll,
      pipelinesSidebarSearch,
      renderSearch,
      scrollState?.isScrollAtStart,
    ],
  )
}

export default PipelinesSidebar
