import {useCallback, useMemo} from 'react'
import type {EntryPointProps} from 'react-relay'

import {useAppSelector} from '../../../hooks/react-redux'
import SidebarPanel from '../SidebarPanel/SidebarPanel'
import {COLLAPSED_SIDEBAR_WIDTH} from '../SidebarPanel/SidebarPanel.consts'
import type {ProjectsSidebarEntryPoint} from '../SidebarPanel/SidebarPanelContent/ProjectsSidebar/ProjectsSidebar.entryPoint'

import {updatePageOffset} from './AdminSidebarPanel.utils'

import {ProjectsTreeContext} from 'src/components/common/ProjectsTree/ProjectsTree.context'

export type NestedEntryPoints = {projectsSidebar?: typeof ProjectsSidebarEntryPoint}

function AdminSidebarPanel({entryPoints}: EntryPointProps<{}, NestedEntryPoints, {}, {}>) {
  const isPinned = useAppSelector(state => state.sidebarSettings.pinned)
  const isPinDisabled = useAppSelector(state => state.sidebarSettings.pinDisabled)
  const isOverlayMode = !isPinned || isPinDisabled

  const {
    pipelineUrlFormat,
    buildTypeUrlFormat,
    templateUrlFormat,
    projectUrlFormat,
    currentId,
    currentNodeType,
  } = useAppSelector(state => state.adminSidebarPanelSettings)

  const contextValue = useMemo(
    () => ({
      isPopup: false,
      isAdmin: true,
      pipelineUrlFormat,
      buildTypeUrlFormat,
      templateUrlFormat,
      projectUrlFormat,
      currentId,
      currentNodeType,
    }),
    [
      pipelineUrlFormat,
      buildTypeUrlFormat,
      currentId,
      currentNodeType,
      projectUrlFormat,
      templateUrlFormat,
    ],
  )

  const handleResize = useCallback(
    (width: number) => {
      updatePageOffset(!isOverlayMode ? width : COLLAPSED_SIDEBAR_WIDTH)
    },
    [isOverlayMode],
  )

  return (
    <ProjectsTreeContext.Provider value={contextValue}>
      <SidebarPanel
        onResize={handleResize}
        projectsSidebarEntryPoint={entryPoints.projectsSidebar}
      />
    </ProjectsTreeContext.Provider>
  )
}

export default AdminSidebarPanel
export type AdminSidebarPanelComponent = typeof AdminSidebarPanel
